def verify_task_complete(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Find the Morning Energy Boost routine for user_id=1
    routine_query = "SELECT id FROM routines WHERE user_id = 1 AND name = 'Morning Energy Boost'"
    initial_routine = safe_query(initial_db_path, routine_query)
    final_routine = safe_query(final_db_path, routine_query)

    # Verify routine still exists and hasn't been duplicated
    if len(initial_routine) != 1 or len(final_routine) != 1:
        return {"result": "others"}

    routine_id = final_routine[0][0]

    # Check initial state: should have days 1,2,3,4,5 (weekdays)
    initial_schedules_query = "SELECT day_of_week, is_active FROM routine_schedules WHERE routine_id = ? ORDER BY day_of_week"
    initial_schedules = safe_query(initial_db_path, initial_schedules_query, (routine_id,))
    final_schedules = safe_query(final_db_path, initial_schedules_query, (routine_id,))

    # Verify initial state has only weekdays (1-5)
    initial_days = sorted([day for day, _ in initial_schedules])
    if initial_days != [1, 2, 3, 4, 5]:
        return {"result": "others"}

    # Verify final state includes weekdays PLUS Saturday (6) and Sunday (0)
    final_days = sorted([day for day, is_active in final_schedules if is_active == 1])
    expected_days = [0, 1, 2, 3, 4, 5, 6]

    if final_days != expected_days:
        return {"result": "others"}

    # Verify Saturday (6) and Sunday (0) entries exist and are active
    saturday_entry = [entry for entry in final_schedules if entry[0] == 6]
    sunday_entry = [entry for entry in final_schedules if entry[0] == 0]

    if len(saturday_entry) != 1 or len(sunday_entry) != 1:
        return {"result": "others"}

    if saturday_entry[0][1] != 1 or sunday_entry[0][1] != 1:
        return {"result": "others"}

    # Verify routine_habits remain unchanged (same habits in same positions)
    habits_query = "SELECT habit_id, position, is_active FROM routine_habits WHERE routine_id = ? ORDER BY position"
    initial_habits = safe_query(initial_db_path, habits_query, (routine_id,))
    final_habits = safe_query(final_db_path, habits_query, (routine_id,))

    # Expected: habits 2, 3, 4 at positions 1, 2, 3, all active
    expected_habits = [(2, 1, 1), (3, 2, 1), (4, 3, 1)]

    if initial_habits != expected_habits or final_habits != expected_habits:
        return {"result": "others"}

    # Verify no extra schedules were added beyond the expected 7 days
    if len(final_schedules) != 7:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
