        tz_idx = max(s.find("+"), s.find("-", 10))
        if tz_idx > 0:
            try:
                dt = datetime.fromisoformat(s[:tz_idx])
                return dt.date()
            except Exception:
                pass
        try:
            dt = datetime.fromisoformat(s)
            return dt.date()
